INSERT INTO assets (asset_tag, category_id, serial_number, brand, model, specs, warranty_expiry, purchase_date, status)
SELECT
  ad.asset_tag,
  cm.id,
  ad.serial_number,
  ad.brand,
  ad.model,
  jsonb_build_object(
    'cpu', NULLIF(ad.cpu, ''),
    'ram', NULLIF(ad.ram, ''),
    'storage', NULLIF(ad.storage, '')
  ) - '{null}'::text[],
  ad.warranty_expiry::date,
  ad.purchase_date::date,
  'in_stock'
FROM asset_data ad
JOIN cat_map cm ON cm.code = ad.category_code;

